rss.channel:
{{ if .IsHome }}梁某银{{ else }}{{ .Title }} - 梁某银{{ end }}
{{ .Permalink }}
{{ .Site.Title }}的最新文章
Hugo -- gohugo.io
{{ with .Site.Language.Locale }}{{.}}{{end}}
{{ with .Site.Copyright }}{{.}}{{end}}
{{ (now.In site.Home.Date.Location).Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
{{ with .OutputFormats.Get "RSS" }}
    {{ printf "" .Permalink .MediaType | safeHTML }}
{{ end }}

{{/* --- 逻辑升级：只抓取 blog 文件夹下的文章 --- */}}
{{ $pages := .Pages }}

{{ if .IsHome }}
  {{/* 核心修改：只选择 section 为 blog 的正规文章，排除 About/Search 等页面 */}}
  {{ $pages = where .Site.RegularPages "Section" "blog" }}
{{ end }}

{{/* 将显示篇数从 15 提高到 50，让订阅源更充实 */}}
{{ $pages = $pages | first 50 }}

{{ range $pages }}


  {{ .Title }}
  {{ .Permalink }}
  {{/* 文章只写了日期时，按平时晚上 21:00 发布来算；构建时还没到 21:00 就用构建时间，免得时间跑到未来 */}}
  {{- $pub := .Date -}}
  {{- if and (eq $pub.Hour 0) (eq $pub.Minute 0) (eq $pub.Second 0) -}}
    {{- $pub = $pub.Add (time.ParseDuration "21h") -}}
    {{- if $pub.After now }}{{ $pub = now.In $pub.Location }}{{ end -}}
  {{- end }}
  {{ $pub.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
  {{ .Permalink }}
  {{ .Content | html }}

{{ end }}
